          },
          {
            "param": "rounding",
            "low": null,
            "high": null
          ,
            "choices": [
              "trunc",
              "round"
            ]
          }
        ]
      ,
        "budget_share": 1.0
      ,
        "why": "Pipelined is the only family that can meet the 32 MSPS throughput constraint. Ranges are narrowed around the accuracy requirements (max_abs_err <= 2^-12) seen in previous rounds, focusing on data_width 14-20 and n_iter 12-18 to balance accuracy and area."
      }
    ]
  ,
    "rationale": "Adding pipelined family to meet throughput and system latency constraints."
  }
}
